<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';import {useRoute} from 'vue-router';import {get,request} from '../api/client'
type Config={title:string;path:string;id:string;search:string;columns:string[];fields?:[string,string,string?][]}
const configs:Record<string,Config>={
 post:{title:'岗位管理',path:'/system/post',id:'postId',search:'postName',columns:['postName','postCode','deptId','status'],fields:[['postName','岗位名称'],['postCode','岗位编码'],['deptId','部门编号'],['postSort','排序','number'],['status','状态 0 正常 / 1 停用']]},
 dict:{title:'字典类型',path:'/system/dict/type',id:'dictId',search:'dictName',columns:['dictName','dictType'],fields:[['dictName','字典名称'],['dictType','字典编码']]},
 'dict-data':{title:'字典数据',path:'/system/dict/data',id:'dictCode',search:'dictType',columns:['dictType','dictLabel','dictValue','dictSort'],fields:[['dictType','字典类型编码'],['dictLabel','标签'],['dictValue','键值'],['dictSort','排序','number'],['isDefault','默认 Y / N']]},
 config:{title:'参数配置',path:'/system/config',id:'configId',search:'configName',columns:['configName','configKey','configType'],fields:[['configName','参数名称'],['configKey','参数键名'],['configValue','参数值'],['configType','内置 Y / N']]},
 notice:{title:'通知公告',path:'/system/notice',id:'noticeId',search:'noticeTitle',columns:['noticeTitle','noticeType','status'],fields:[['noticeTitle','标题'],['noticeType','类型 1 通知 / 2 公告'],['noticeContent','正文','textarea'],['status','状态 0 正常 / 1 关闭']]},
 client:{title:'客户端配置（只读）',path:'/system/client',id:'id',search:'clientId',columns:['clientId','clientKey','deviceType','status']},
 login:{title:'登录日志',path:'/monitor/logininfor',id:'infoId',search:'userName',columns:['userName','ipaddr','status','loginTime','msg']},
 online:{title:'在线工作人员',path:'/monitor/online',id:'userId',search:'userName',columns:['userName','deptName','ipaddr','loginTime']},
 cache:{title:'缓存监控',path:'/monitor/cache',id:'id',search:'',columns:[]}
}
const route=useRoute(),module=String(route.params.module),config=configs[module],rows=ref<any[]>([]),total=ref(0),page=ref(1),query=ref(''),error=ref(''),busy=ref(false),screen=ref('list'),model=ref<Record<string,any>>({}),selected=ref<any>(null),cache=ref<any>(null),checked=ref<string[]>([])
const names:Record<string,string>={postName:'岗位',postCode:'编码',deptId:'部门编号',status:'状态',dictName:'名称',dictType:'字典类型',dictLabel:'标签',dictValue:'键值',dictSort:'排序',configName:'名称',configKey:'键名',configType:'内置',noticeTitle:'标题',noticeType:'类型',clientId:'客户端',clientKey:'客户端标识',deviceType:'设备',userName:'账号',ipaddr:'IP',loginTime:'登录时间',msg:'结果',deptName:'部门'}
const removable=computed(()=>!!config?.fields)
async function act(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function load(){if(!config)return;if(module==='cache'){cache.value=await get(config.path);return}const data=await get(config.path+'/list',{pageNum:page.value,pageSize:20,[config.search]:query.value});rows.value=data.rows||[];total.value=data.total||0;checked.value=[]}
async function open(row:any=null,edit=true){await act(async()=>{selected.value=row;model.value=row?await get(config.path+'/'+row[config.id]):{};if(!row)for(const [key,,type] of config.fields||[])model.value[key]=type==='number'?0:key==='status'?'0':key==='configType'||key==='isDefault'?'N':'';screen.value=edit?'form':'detail'})}
async function save(){await act(async()=>{const data={...model.value};if(module==='post'&&!/^\d+$/.test(String(data.deptId)))throw new Error('请选择有效部门编号');await request(selected.value?'PUT':'POST',config.path,data);screen.value='list';await load()})}
async function remove(ids:string[]){if(!ids.length||!confirm('确认删除选中的 '+ids.length+' 条记录？受引用保护的记录可能被拒绝。'))return;await act(async()=>{await request('DELETE',config.path+'/'+ids.map(encodeURIComponent).join(','));await load()})}
onMounted(()=>act(load))
</script><template><section v-if="config"><div class="title-row"><h1>{{ config.title }}</h1><button v-if="screen!=='list'" class="quiet" @click="screen='list'">返回列表</button></div><p class="muted">公司基座接口，独立权限校验与操作日志。此处配置不自动替代业务目录或私有文件存储。</p><p class="error" role="alert">{{ error }}</p><template v-if="screen==='list'"><form v-if="module!=='cache'" class="panel actions" @submit.prevent="page=1;act(load)"><input v-model="query" :placeholder="'按'+(names[config.search]||config.search)+'搜索'"/><button :disabled="busy">搜索</button><button v-if="config.fields" type="button" :disabled="busy" @click="open()">新建</button><button v-if="removable" type="button" class="danger" :disabled="busy||!checked.length" @click="remove(checked)">删除所选</button></form><div v-if="module==='cache'&&cache" class="panel"><h2>Redis 状态</h2><p>键总量 {{ cache.dbSize }}</p><p>版本 {{ cache.info?.redis_version }} · 内存 {{ cache.info?.used_memory_human }}</p><button class="quiet" @click="act(load)">刷新状态</button></div><div v-else class="panel scroll"><table><thead><tr><th v-if="removable">选择</th><th v-for="key in config.columns" :key="key">{{ names[key]||key }}</th><th v-if="config.fields">操作</th></tr></thead><tbody><tr v-for="(r,i) in rows" :key="r[config.id]||i"><td v-if="removable"><input v-model="checked" type="checkbox" :value="String(r[config.id])" :aria-label="'选择记录 '+r[config.id]"/></td><td v-for="key in config.columns" :key="key">{{ r[key]??'—' }}</td><td v-if="config.fields"><div class="actions"><button class="quiet" @click="open(r,false)">详情</button><button class="secondary" @click="open(r)">编辑</button></div></td></tr></tbody></table><p v-if="!rows.length">暂无记录</p><div class="actions"><button class="quiet" :disabled="busy||page===1" @click="page--;act(load)">上一页</button><span>第 {{ page }} 页 · {{ total }} 条</span><button class="quiet" :disabled="busy||page*20>=total||module==='online'" @click="page++;act(load)">下一页</button></div></div></template><form v-if="screen==='form'" class="panel" @submit.prevent="save"><label v-for="[key,title,type] in config.fields" :key="key">{{ title }}<textarea v-if="type==='textarea'" v-model="model[key]" required/><input v-else-if="type==='number'" v-model.number="model[key]" type="number" required/><input v-else v-model="model[key]" maxlength="500" required/></label><button :disabled="busy">保存</button></form><div v-if="screen==='detail'" class="panel"><div v-for="[key,title] in config.fields" :key="key"><h3>{{ title }}</h3><p style="white-space:pre-wrap">{{ model[key] }}</p></div></div></section><section v-else><h1>模块不存在</h1></section></template>
